class Commando < Formula
  desc "Colorful TUI that turns a command's man page into a form for its options"
  homepage "https://github.com/lonedevel/commando"
  license "Apache-2.0"

  head do
    url "https://github.com/lonedevel/commando.git", branch: "main"
    depends_on "go" => :build
  end

  # Generated by scripts/update-formula.sh from the release's checksums.txt.
  on_macos do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.5.0/commando_0.5.0_darwin_arm64.tar.gz"
      sha256 "0ac534d2850f734fec396960d504dd9428792be51297712441be1dc4d0729f8b"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.5.0/commando_0.5.0_darwin_amd64.tar.gz"
      sha256 "57556b99162b6a8e0d49de43efbe20416fa4c8c2fb306e2a9a11308395b3ae65"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.5.0/commando_0.5.0_linux_arm64.tar.gz"
      sha256 "2e48c23a7984d2e8ae29b42e95d96198feeaad514b0381f3db3d93e4c7009706"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.5.0/commando_0.5.0_linux_amd64.tar.gz"
      sha256 "772e892914de6b92285dd1bb332ead8452a540fbf72816330fbfb5b46165d5f5"
    end
  end

  def install
    if build.head?
      system "go", "build", *std_go_args(ldflags: "-s -w -X main.version=#{version}"), "./cmd/commando"
    else
      bin.install "commando"
    end
  end

  def caveats
    <<~EOS
      To edit the command you're typing with Ctrl-X Ctrl-O, add to your shell config:
        zsh:  eval "$(commando --init zsh)"
        bash: eval "$(commando --init bash)"
        fish: commando --init fish | source
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/commando --version")
    assert_match "bindkey", shell_output("#{bin}/commando --init zsh")

    # Parse a manual without needing a terminal.
    ENV["COMMANDO_CACHE_DIR"] = testpath/"cache"
    output = shell_output("#{bin}/commando --dump --no-cache ls")
    assert_match "\"names\"", output
  end
end
